from pybricks.hubs import PrimeHub
from pybricks.parameters import Button, Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, ForceSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up all devices.
prime_hub_ = PrimeHub()
color_sensor = ColorSensor(Port.E)
Touch_Sensor = ForceSensor(Port.F)
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right = Motor(Port.B, Direction.CLOCKWISE)
drive_base = DriveBase(Left, Right, 66, 150)
MM_Left = Motor(Port.C, Direction.CLOCKWISE)
MM_Right = Motor(Port.D, Direction.CLOCKWISE)

# Initialize variables.
myWhite = 100
myBlack = 0
targetValue = 50
baseSpeed = 200
turnAmount = 10
run_number = 0
max_runs = 8
running = 0
targetAngle = 0
currentAngle = 0
error = 0
correction = 0
Kp = 2
distance = 0

def Run_1():
    print('Begin Mission 1')
    drive_base.reset(0, 0)
    prime_hub_.display.char('A')
    print('Mission A')

def Run_2():
    drive_base.reset(0, 0)
    prime_hub_.display.char('B')
    print('Mission B')

def Run_3():
    drive_base.reset(0, 0)
    prime_hub_.display.char('C')
    print('Mission C')

def Run_4():
    drive_base.reset(0, 0)
    drive_base.settings(straight_acceleration=500)
    drive_base.settings(straight_speed=500)
    drive_base.straight(760)
    print(drive_base.angle())
    # motor dip 1st
    drive_base.turn(15)
    MM_Left.run_angle(190, 20)
    drive_base.straight(40)
    MM_Left.run_angle(190, 40)
    # Go Back!
    drive_base.straight(-50)
    drive_base.settings(straight_speed=800)
    drive_base.turn(-20)
    drive_base.straight(-900)

def Run_5():
    drive_base.reset(0, 0)
    prime_hub_.display.char('C')
    print('Mission E')

def Run_6():
    drive_base.reset(0, 0)
    prime_hub_.display.char('C')
    print('Mission F')

def Run_8():
    drive_base.reset(0, 0)
    DriveStraight(750, 500)
    drive_base.turn(-100)
    print(drive_base.angle())
    DriveStraight(150, 330)
    drive_base.settings(straight_speed=500)
    drive_base.straight(-130)
    drive_base.turn(-35)
    drive_base.straight(-120)
    drive_base.turn(100)
    # then turn and come back!
    drive_base.turn(-30)
    DriveStraight(80, 400)
    drive_base.turn(90)
    DriveStraight(750, 700)
    drive_base.reset(0, 0)

def run_7():
    pass

def DriveStraight(dist, speed):
    global targetAngle, baseSpeed, currentAngle, error, correction
    drive_base.use_gyro(True)
    drive_base.reset(0, 0)
    targetAngle = 0
    drive_base.settings(straight_acceleration=400)
    baseSpeed = speed
    while not drive_base.distance() >= dist:
        currentAngle = drive_base.angle()
        error = targetAngle - currentAngle
        correction = Kp * error
        drive_base.drive(baseSpeed, correction)
    drive_base.straight(0)


# The main program starts here.
# Mission Selector Program
# Overriding Center Button from stopping a program when running.
prime_hub_.system.set_stop_button(Button.BLUETOOTH)
run_number = 1
max_runs = 8
running = 1
prime_hub_.display.off()
# Hub display turned off. Waiting for Mission Selection
# Main program runs forever until Center Button is pressed
while running:
    # Scroll LEFT for mission selection
    if Button.LEFT in prime_hub_.buttons.pressed():
        # Wait until button is released
        while Button.LEFT in prime_hub_.buttons.pressed():
            wait(0)
        run_number = run_number - 1
        if run_number < 1:
            run_number = max_runs
            wait(200)
        print('Mission:', run_number, sep=", ")
        prime_hub_.display.number(run_number)
    # Scroll RIGHT for mission selection
    if Button.RIGHT in prime_hub_.buttons.pressed():
        while Button.RIGHT in prime_hub_.buttons.pressed():
            wait(0)
        run_number = run_number + 1
        if run_number > max_runs:
            run_number = 1
            wait(200)
        print('Mission:', run_number, sep=", ")
        prime_hub_.display.number(run_number)
    # Center Button for selecting and running missions
    if Button.CENTER in prime_hub_.buttons.pressed():
        while Button.CENTER in prime_hub_.buttons.pressed():
            wait(0)
        print('Touch Button Released')
        # Showing mission number once again. Display should be showing it already
        prime_hub_.display.number(run_number)
        if run_number == 1:
            print('Calling Mission 1')
            Run_1()
        elif run_number == 2:
            Run_2()
        elif run_number == 3:
            Run_3()
        elif run_number == 4:
            Run_4()
        elif run_number == 5:
            Run_5()
        elif run_number == 6:
            Run_6()
        elif run_number == 7:
            run_7()
        elif run_number == 8:
            Run_8()
        else:
            # Do Nothing
            pass
